'use strict';
const root=document.getElementById('live-app');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={
 moon:'M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10Z', sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5',
 plus:'M12 5v14M5 12h14', runs:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',
 link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',
 arrow:'M5 12h14m-6-6 6 6-6 6', back:'M19 12H5m6-6-6 6 6 6', chevron:'m9 5 7 7-7 7',
 folder:'M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z',
 file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6Zm0 0v6h6M8 13h8M8 17h5',
 code:'m8 8-4 4 4 4m8-8 4 4-4 4m-3-10-2 20', download:'M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4',
 refresh:'M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 13-3l2 2M4 17l2 2a8 8 0 0 0 13-3',
 more:'M5 12h.01M12 12h.01M19 12h.01', chat:'M21 15a3 3 0 0 1-3 3H8l-5 3V6a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3v9Z',
 terminal:'m5 7 5 5-5 5m8 0h6', box:'m12 3 9 5v9l-9 5-9-5V8l9-5Zm0 9 9-4M3 8l9 4v10',
 check:'m5 12 4 4L19 6', clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
 logout:'M9 4H4v16h5m5-13 5 5-5 5m-6-5h11', search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',
 settings:'M4 7h16M4 17h16M8 4v6m8 4v6', close:'m6 6 12 12M6 18 18 6', lock:'M6 10h12v11H6V10Zm2 0V6a4 4 0 0 1 8 0v4',
 spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z', info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z'
};
const icon=(name,extra='')=>`<svg class="icon ${extra}" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]??paths.file}"/></svg>`;
const state={session:null,catalog:null,connection:null,github:null,githubInstallations:[],githubInstallationId:"",repositories:null,repoForm:{id:"",baseBranch:"",checkCommand:"",publishMode:"manual"},runs:[],run:null,stream:null,cursor:0,seen:new Set(),drafts:{},busy:false,error:'',route:'',epoch:0,pending:new Map(),
 form:{title:'',instructions:'',template:'environment-check'},tab:'activity',files:null,fileRun:null,workspacePath:'',exportPath:'',selectedPath:null,fileRequest:0,previewRequest:0,systemEvents:false,runSearch:'',runFilter:'all'};
const label=value=>String(value??'').replaceAll('-',' ').replaceAll('_',' ');
const time=value=>new Date(value).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
const shortTime=value=>new Date(value).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});
const templateName=id=>({'codex-task':'Codex task','environment-check':'Environment check','failure-check':'Failure check'}[id]??label(id));
const statusName=value=>({'review':'Ready for review','browsing':'Files open','suspended':'Paused','opening-workspace':'Opening files','closing-workspace':'Closing files','preparing':'Preparing','recovery-required':'Needs attention'}[value]??label(value));
const statusBadge=r=>`<span class="status status-${esc(r.state)}"><span class="status-dot"></span>${esc(statusName(r.state))}</span>`;
const button=(text,action,kind='',disabled=false,symbol='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${disabled?'disabled':''}>${symbol?icon(symbol):''}${text}</button>`;
const iconButton=(text,action,symbol,extra='')=>`<button type="button" class="btn icon-button" data-action="${action}" aria-label="${esc(text)}" title="${esc(text)}" ${extra}>${icon(symbol)}</button>`;
function themeButton(){const dark=window.portalTheme?.current()==='dark';return `<button type="button" class="btn icon-button theme-toggle" data-action="theme" aria-label="Dark mode" aria-pressed="${dark}" title="Switch to ${dark?'light':'dark'} mode">${icon(dark?'sun':'moon')}</button>`;}
function updateThemeButtons(){const dark=window.portalTheme?.current()==='dark';document.querySelectorAll('[data-action="theme"]').forEach(el=>{el.setAttribute('aria-pressed',String(dark));el.title=`Switch to ${dark?'light':'dark'} mode`;el.innerHTML=icon(dark?'sun':'moon');});}
window.addEventListener('portal-theme-change',updateThemeButtons);
function fileSize(bytes){if(bytes==null)return '—';if(bytes<1024)return `${bytes} B`;if(bytes<1024**2)return `${(bytes/1024).toFixed(bytes<10240?1:0)} KB`;return `${(bytes/1024**2).toFixed(1)} MB`;}
function fileType(name){const ext=name.split('.').pop();return name.includes('.')?`${ext.toUpperCase()} file`:'File';}
function emptyState(symbol,title,description,actions=''){return `<div class="empty-state"><span class="empty-icon">${icon(symbol)}</span><h3>${title}</h3><p>${description}</p>${actions}</div>`;}
async function api(path,{method='GET',body,key}={}){
 const headers={};if(body!==undefined)headers['Content-Type']='application/json';
 if(method!=='GET'){headers['X-CSRF-TOKEN']=state.session?.csrfToken??'';if(key)headers['Idempotency-Key']=key;}
 const response=await fetch('/api'+path,{method,headers,credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body)});
 const data=await response.json().catch(()=>null);
 if(!response.ok){
  if(response.status===401&&path!=='/login'){clearPrivateState();state.session=null;await session();renderLogin();}
  throw new Error(data?.error??`Request failed (${response.status}).`);
 }
 return data;
}
// An uncertain POST retains its key; retrying cannot create a duplicate run.
async function mutate(path,body){const fingerprint=JSON.stringify([path,body]);const key=state.pending.get(fingerprint)??crypto.randomUUID();state.pending.set(fingerprint,key);const result=await api(path,{method:'POST',body,key});state.pending.delete(fingerprint);return result;}
function closeStream(){state.stream?.close();state.stream=null;}
function clearPrivateState(){closeStream();state.epoch++;state.fileRequest++;state.previewRequest++;state.run=null;state.runs=[];state.drafts={};state.connection=null;state.github=null;state.githubInstallations=[];state.githubInstallationId="";state.repositories=null;state.repoForm={id:"",baseBranch:"",checkCommand:"",publishMode:"manual"};state.catalog=null;state.files=null;state.fileRun=null;state.pending.clear();state.form={title:'',instructions:'',template:'environment-check'};state.runSearch='';state.runFilter='all';state.workspacePath='';state.exportPath='';state.selectedPath=null;state.cursor=0;state.seen.clear();state.tab='activity';}
function error(message){state.error=message;const el=document.getElementById('live-error');if(el){el.textContent=message;el.hidden=!message;}}
async function session(){state.session=await api('/session');return state.session.authenticated;}
function renderLogin(){root.innerHTML=`<main class="login-page"><section class="login-card"><div class="login-heading"><div class="brand"><span class="brand-mark">${icon('box')}</span>Agent Desk</div>${themeButton()}</div><h1>Welcome back.</h1><p class="muted">Sign in to your private workspace.</p><div id="live-error" class="alert error" role="alert" hidden></div><form id="login-form"><label class="field" for="username"><span>Username</span><input id="username" name="username" autocomplete="username" required></label><label class="field" for="password"><span>Password</span><input id="password" name="password" type="password" autocomplete="current-password" required></label><button class="btn primary wide" type="submit">Sign in ${icon('arrow')}</button></form><p class="login-note">Use your portal login, not your ChatGPT password.</p></section></main>`;}
function shell(content){
 const title=state.route==='new'?'New run':state.route==='connections'?'Connections':state.route.startsWith('runs/')?'Run':'Runs';
 root.innerHTML=`<a class="skip-link" href="#main-content">Skip to content</a><div class="app-layout"><aside class="sidebar"><a class="brand" href="#/runs"><span class="brand-mark">${icon('box')}</span>Agent Desk</a><a class="new-run-link ${state.route==='new'?'selected':''}" href="#/new">${icon('plus')} New run</a><nav class="navigation" aria-label="Main navigation"><a href="#/runs" ${state.route.startsWith('runs')?'aria-current="page"':''}>${icon('runs')}<span>Runs</span><span id="run-count" class="nav-count">${state.runs.length}</span></a><a href="#/connections" ${state.route==='connections'?'aria-current="page"':''}>${icon('link')}<span>Connections</span></a></nav><div class="sidebar-bottom"><div class="appearance-controls"><span class="lab-label">${icon('lock')} Demo deployment</span>${themeButton()}</div><details class="account-menu"><summary><span class="avatar">${esc((state.session.username??'U')[0].toUpperCase())}</span><span>${esc(state.session.username)}</span>${icon('more')}</summary><div class="menu-content">${button('Sign out','logout','','','logout')}<a href="/demo">Open mock demo ${icon('arrow')}</a></div></details></div></aside><main id="main-content" class="main-content" tabindex="-1"><header class="page-heading"><div><div class="eyebrow">WORKSPACE</div><h1 id="page-title">${title}</h1><div id="page-subtitle" class="page-subtitle">${state.route==='new'?'Start a task. Keep your workspace.':state.route==='connections'?'The accounts your agents can use.':state.route==='runs'?'Your work, ready to continue.':''}</div></div><div id="page-actions"></div></header><div id="live-error" class="alert error" role="alert" hidden></div>${content}</main></div>`;
 if(state.error)error(state.error);
}
function taskHint(template){return template==='codex-task'?'Describe what to create or change in the workspace.':template==='failure-check'?'This test intentionally exits with an error to verify failure reporting. No AI is called.':'This runs a fixed environment test and saves your note. No AI is called.';}
function renderNew(){
 const selected=state.catalog.templates.find(t=>t.id===state.form.template)??state.catalog.templates[0];state.form.template=selected.id;
 shell(`<div class="new-run-layout"><section class="panel form-panel"><form id="run-form"><label class="field" for="template"><span>Task type</span><select id="template" name="template">${state.catalog.templates.map(t=>`<option value="${esc(t.id)}" ${t.id===selected.id?'selected':''}>${esc(templateName(t.id))}</option>`).join('')}</select></label><label class="field" for="title"><span>Run name</span><input id="title" name="title" maxlength="120" placeholder="e.g. Create a project README" value="${esc(state.form.title)}" required></label><label class="field" for="instructions"><span id="instructions-label">${selected.id==='codex-task'?'Instructions':'Note'}</span><textarea id="instructions" name="instructions" maxlength="8000" placeholder="What would you like to get done?" required>${esc(state.form.instructions)}</textarea></label><p id="template-help" class="field-help">${taskHint(selected.id)}</p><div id="connection-notice"></div><div id="repository-form"></div><details class="settings-details"><summary>${icon('settings')} Execution settings ${icon('chevron')}</summary><dl class="settings-grid"><div><dt>Environment</dt><dd>Private gVisor sandbox</dd></div><div><dt>Resources</dt><dd id="resource-summary"></dd></div><div><dt>Workspace</dt><dd>A separate /workspace per run</dd></div><div><dt>After each turn</dt><dd>Save workspace and pause</dd></div></dl><p class="field-help">One run at a time. Codex: 5 minutes / 8 model requests per turn. Optional GitHub checkout; no command internet access. Shell commands run automatically inside the sandbox.</p></details><div class="form-footer"><span>${icon('lock')} Only you can access this run</span><button class="btn primary" type="submit">Start run ${icon('arrow')}</button></div></form></section><aside class="new-run-note"><span class="note-icon">${icon('spark')}</span><h2>Start small.<br>Keep going.</h2><p>Your workspace stays with the run. Review the output, browse your files, then continue with feedback.</p><div id="prompt-example" class="note-example"><span>TRY AN INSTRUCTION LIKE</span><p>“Create a Python script that reads a CSV and prints a summary. Add a small test and run it.”</p></div></aside></div>`);
 updateNewSettings();
}
function updateNewSettings(){renderRepositoryForm();const codex=state.form.template==='codex-task';document.getElementById('instructions-label').textContent=codex?'Instructions':'Note';document.getElementById('template-help').textContent=taskHint(state.form.template);document.getElementById('resource-summary').textContent=codex?'1 CPU · 1 GiB':'1 CPU · 512 MiB';document.getElementById('instructions').placeholder=codex?'What would you like to create or change?':'Add a note to save with this test…';document.getElementById('prompt-example').hidden=!codex;const connected=state.catalog.connections?.[0]?.state==='connected';document.getElementById('connection-notice').innerHTML=codex&&!connected?`<div class="inline-notice">${icon('link')}<span>Connect ChatGPT before starting a Codex task.</span><a href="#/connections">Connect ${icon('arrow')}</a></div>`:'';}
function renderRepositoryForm(){
 const el=document.getElementById('repository-form');if(!el)return;
 if(state.form.template!=='codex-task'||!state.catalog.githubEnabled){el.innerHTML='';return;}
 const f=state.repoForm;
 el.innerHTML=`<details class="settings-details repository-settings" ${f.id?'open':''}><summary>${icon('code')} GitHub repository <span class="muted">Optional</span> ${icon('chevron')}</summary>${state.repositories===null?`<p class="field-help">Use a selected repository from your GitHub App.</p>${button('Choose repository','load-repositories','','','folder')} <a href="#/connections">Connect GitHub</a>`:`<label class="field" for="repository-id"><span>Repository</span><select id="repository-id"><option value="">None · empty workspace</option>${state.repositories.map(r=>`<option value="${r.id}" ${String(r.id)===f.id?'selected':''}>${esc(r.fullName)}</option>`).join('')}</select></label>${!state.repositories.length?'<p class="field-help">No repositories available. Check your selected repositories in Connections.</p>':''}${f.id?`<label class="field" for="repository-baseBranch"><span>Base branch</span><input id="repository-baseBranch" value="${esc(f.baseBranch)}" maxlength="200" required></label><label class="field" for="repository-checkCommand"><span>Required check</span><input id="repository-checkCommand" value="${esc(f.checkCommand)}" placeholder="e.g. python -m unittest" maxlength="1000" required></label><p class="field-help">Runs inside the sandbox before publication. Use a check that works without internet.</p><label class="field" for="repository-publishMode"><span>Publishing</span><select id="repository-publishMode"><option value="manual" ${f.publishMode==='manual'?'selected':''}>Wait for my review (default)</option><option value="auto" ${f.publishMode==='auto'?'selected':''}>Automatically push & create draft PR</option></select></label><p class="field-help">${f.publishMode==='auto'?'After each successful turn and required check, publish committed changes to this run’s branch.':'Review the committed diff, then choose Push & create draft PR.'} Never merges. Small repositories only: 8 MiB bundle limit.</p>`:''}`}</details>`;
}
function publicationPanel(r){
 const el=document.getElementById('publication-panel');if(!el)return;if(!r.repository){el.hidden=true;return;}el.hidden=false;
 const p=r.publication??{},ready=['review','suspended'].includes(r.state)&&['ready','failed'].includes(p.state)&&p.head&&p.checkedTurn===r.turn;
 const key=JSON.stringify([r.state,r.turn,p,state.busy]);if(el.dataset.key===key)return;el.dataset.key=key;
 el.innerHTML=`<div class="publication-heading"><div><h2>Changes & publishing</h2><p class="field-help">${esc(r.repository.fullName)} · ${esc(r.repository.baseBranch)} · ${r.repository.publishMode==='auto'?'Automatic draft PR':'Wait for review'}</p></div><span class="status">${esc(r.state==='publishing'?'Publishing…':p.state==='ready'?'Checks passed':p.state==='published'?'Published':p.state==='failed'?'Needs retry':p.state==='blocked'?'Not publishable':'Awaiting changes')}</span></div>${p.error?`<p class="alert error">${esc(p.error)}</p>`:''}${p.head?`<p class="field-help mono">${esc(r.publishBranch)} · ${esc(p.head.slice(0,12))}</p>`:''}${p.diff?`<details class="review-details"><summary>Review committed changes ${icon('chevron')}</summary><pre class="git-preview" tabindex="0">${esc(p.diff)}</pre></details>`:''}${p.checkedTurn?`<details class="review-details"><summary>Required check · turn ${p.checkedTurn} ${icon('chevron')}</summary><code>${esc(r.repository.checkCommand)}</code><pre class="git-preview" tabindex="0">${esc(p.checks||'(No check output)')}</pre><p class="field-help">Local check only. Review the agent’s report and GitHub CI before merging.</p></details>`:''}<div class="publication-actions">${ready?button(p.pullRequestUrl?'Push & update PR':'Push & create draft PR','publish','primary',state.busy,'arrow'):''}${p.pullRequestUrl?`<a class="btn" href="${esc(p.pullRequestUrl)}" target="_blank" rel="noopener noreferrer">Open PR #${p.pullRequestNumber} ${icon('arrow')}</a>`:''}</div>`;
}
function runRows(){
 const query=state.runSearch.toLocaleLowerCase();
 const runs=state.runs.filter(r=>(!query||`${r.title} ${templateName(r.template)}`.toLocaleLowerCase().includes(query))&&(state.runFilter==='all'||(state.runFilter==='finished'?['completed','cancelled'].includes(r.state):!['completed','cancelled'].includes(r.state))));
 if(!runs.length)return emptyState('runs',state.runs.length?'No matching runs':'Your next idea starts here',state.runs.length?'Try a different name or filter.':'Start a task, follow its progress, and come back to your saved work.',state.runs.length?'':'<a class="btn primary" href="#/new">New run</a>');
 return `<div class="run-table-heading" aria-hidden="true"><span>Name</span><span>Status</span><span>Updated</span><span></span></div>${runs.map(r=>`<a class="run-row" href="#/runs/${encodeURIComponent(r.id)}"><span class="run-name"><span class="run-icon">${icon(r.template==='codex-task'?'spark':'terminal')}</span><span><strong>${esc(r.title)}</strong><small>${esc(templateName(r.template))} <span>·</span> Turn ${r.turn}</small></span></span>${statusBadge(r)}<time datetime="${esc(r.updatedAt)}">${esc(time(r.updatedAt))}</time>${icon('chevron','row-chevron')}</a>`).join('')}`;
}
function renderRuns(){shell(`<section class="panel runs-panel"><div class="runs-toolbar"><label class="search-field">${icon('search')}<input id="run-search" type="search" aria-label="Search runs" placeholder="Search runs…" value="${esc(state.runSearch)}"></label><select id="run-filter" aria-label="Filter runs"><option value="all" ${state.runFilter==='all'?'selected':''}>All runs</option><option value="open" ${state.runFilter==='open'?'selected':''}>Open runs</option><option value="finished" ${state.runFilter==='finished'?'selected':''}>Finished</option></select></div><div id="run-list">${runRows()}</div></section>`);}
function githubInstallationForm(){
 const list=state.githubInstallations;if(!list.length)return '';
 const selected=list.find(i=>String(i.id)===state.githubInstallationId)??list[0];state.githubInstallationId=String(selected.id);const all=selected.repositorySelection==='all';
 return `<form id="github-install-form" class="github-install-form"><label class="field">Installation<select id="github-installation" name="installation">${list.map(i=>`<option value="${i.id}" ${i.id===selected.id?'selected':''}>${esc(i.account)} · ${i.repositorySelection==='all'?'All repositories':'Selected repositories'}</option>`).join('')}</select></label>${all?'<div class="github-scope-warning"><strong>Access to all current and future repositories</strong><p>Your GitHub App can read code, push branches and create PRs across this account. Choose selected repositories on GitHub for narrower access.</p><label><input type="checkbox" name="allowAllRepositories" required> I allow this App to access all repositories.</label><p>Each task still uses a temporary token scoped to its one repository.</p></div>':''}<button type="submit" class="btn primary">${all?'Confirm all-repository access':'Use this installation'}</button></form>`;
}
function githubCard(){const g=state.github;if(!g?.enabled)return '';return `<section class="panel connection-panel github-panel"><div class="connection-heading"><span class="connection-logo">${icon('code')}</span><div><h2>GitHub</h2><p>${g.state==='connected'?(g.allRepositoriesAllowed?'All repositories allowed.':'Selected repositories only.'):'Choose which repositories agents can use.'}</p></div><span class="status ${g.state==='connected'?'status-completed':''}"><span class="status-dot"></span>${g.state==='connected'?'Connected':g.state==='install-required'?'Choose repositories':'Not connected'}</span></div>${g.account?`<p>${esc(g.account)}</p>`:''}<div class="connection-footer"><p class="field-help">Your own GitHub App. Credentials stay outside the sandbox.</p><div class="button-group">${g.state==='disconnected'?button('Connect GitHub','github-setup','primary',false,'link'):`<a class="btn" href="${esc(g.installUrl)}" target="_blank" rel="noopener noreferrer">Choose repositories ${icon('arrow')}</a>${button('Refresh installations','github-refresh')}${button('Disconnect','github-disconnect','subtle danger')}`}</div></div>${githubInstallationForm()}<details class="help-details"><summary>Setup & permissions ${icon('chevron')}</summary><p>Create your private App on GitHub and grant Contents and Pull requests write access. “Only select repositories” is recommended. “All repositories” is supported after an explicit confirmation here. The portal keeps the App key encrypted outside the sandbox. Disconnecting here does not uninstall the App on GitHub.</p></details></section>`;}
function renderConnections(){
 const c=state.connection,connected=!!c?.connectionId,pending=c?.state==='pending';
 shell(`<section class="panel connection-panel"><div class="connection-heading"><span class="connection-logo">${icon('spark')}</span><div><h2>ChatGPT / Codex</h2><p>Use your personal subscription.</p></div><span class="status ${connected?'status-completed':''}"><span class="status-dot"></span>${pending?'Awaiting sign-in':c?.state==='reconnect-required'?'Reconnect needed':connected?'Connected':'Not connected'}</span></div>${c?.error?`<div class="alert error" role="alert">${esc(c.error)}</div>`:''}${connected?`<div class="connection-account"><span class="avatar">${esc((c.email??'C')[0].toUpperCase())}</span><div><strong>${esc(c.email??'ChatGPT account')}</strong><span>${esc(c.plan??'Personal account')}</span></div>${icon('check')}</div>`:''}${pending?`<div class="device-login"><h3>Finish signing in</h3><p>Open OpenAI’s page and enter this code.</p><div class="device-code">${esc(c.userCode)}</div><a class="btn primary" href="${esc(c.verificationUrl)}" target="_blank" rel="noopener noreferrer">Open OpenAI ${icon('arrow')}</a><p class="field-help">Use only the code you requested here. Never share it in chat.<br>Expires ${esc(time(c.expiresAt))}. This page updates automatically.</p></div>`:''}<div class="connection-footer"><p class="field-help">Your credentials stay outside the sandbox.</p><div class="button-group">${!pending?button(connected?'Reconnect':'Connect ChatGPT','codex-login',connected?'':'primary',!c?.enabled,'link'):button('Cancel sign-in','codex-cancel')}${connected?button('Disconnect','codex-disconnect','subtle danger'):''}</div></div><details class="help-details"><summary>Sign-in help & privacy ${icon('chevron')}</summary><p>This uses OpenAI’s device-code sign-in. If it is blocked, enable device login in ChatGPT security settings. Your ChatGPT password stays on OpenAI’s page.</p><p>The encrypted connection belongs to your portal login. No API-key billing fallback is used. Disconnect removes the portal connection; revoke sessions in ChatGPT if needed.</p></details></section>${githubCard()}`);
}
function controls(r){
 const resumable=['review','suspended','failed'].includes(r.state),running=['running','preparing','resuming'].includes(r.state),terminal=['completed','cancelled'].includes(r.state),browsing=['browsing','opening-workspace'].includes(r.state);
 return `${browsing?button('Close workspace','close-workspace','','','close'):''}${running||r.state==='recovery-required'?button('Pause run','suspend','','','clock'):''}${!terminal?`<details class="action-menu"><summary class="btn icon-button" aria-label="More run actions" title="More run actions">${icon('more')}</summary><div class="menu-content">${resumable?button('Finish run','finish','','','check'):''}${button('Cancel run','cancel','danger',['cancelling','finishing','publishing'].includes(r.state),'close')}</div></details>`:''}`;
}
function renderDetail(r){
 state.run=r;state.files=null;state.fileRun=r.id;state.tab='activity';state.workspacePath='';state.exportPath='';state.selectedPath=null;state.cursor=0;state.seen.clear();state.fileRequest++;state.previewRequest++;
 shell(`<section class="panel run-panel"><header class="run-toolbar"><div class="tabs" role="tablist" aria-label="Run views"><button type="button" id="activity-tab" role="tab" aria-controls="activity-panel" aria-selected="true" data-action="activity">${icon('chat')} Conversation</button><button type="button" id="files-tab" role="tab" aria-controls="files-panel" aria-selected="false" tabindex="-1" data-action="files">${icon('folder')} Files</button></div><span id="stream-state" class="stream-state">Connecting…</span></header><div id="activity-panel" role="tabpanel" aria-labelledby="activity-tab"><div class="activity-toolbar"><label><input id="system-events" type="checkbox" ${state.systemEvents?'checked':''}> Show system events</label></div><div id="events" class="conversation ${state.systemEvents?'show-system':''}" aria-label="Run conversation"><div class="events-empty">Loading conversation…</div></div><form id="feedback-form" class="composer"><label for="feedback">Continue this run</label><textarea id="feedback" placeholder="Tell the agent what to do next…" maxlength="8000" rows="2">${esc(state.drafts[r.id]??'')}</textarea><div class="composer-footer"><span id="feedback-hint"></span><button class="btn primary" id="resume-button" type="submit">Resume ${icon('arrow')}</button></div></form><div id="run-outcome" class="run-outcome" hidden></div></div><section id="files-panel" role="tabpanel" aria-labelledby="files-tab" hidden></section><div id="run-error" class="alert error run-error" role="alert" hidden></div></section><section id="publication-panel" class="panel publication-panel" hidden></section><details class="run-details"><summary>${icon('info')} Run details ${icon('chevron')}</summary><dl id="detail-settings" class="settings-grid"></dl><p>Ready for review means the turn ended, not that every requested change succeeded. Check the agent’s report and files.</p></details>`);
 updateDetail(r);openStream(r.id);
}
function updateDetail(r){
 const changed=state.run?.state!==r.state||state.run?.platformPhase!==r.platformPhase;state.run=r;
 publicationPanel(r);
 const title=document.getElementById('page-title');if(!title)return;
 title.textContent=r.title;document.getElementById('page-subtitle').innerHTML=`${statusBadge(r)}<span>${esc(templateName(r.template))}</span><span class="meta-dot">·</span><span>Turn ${r.turn}</span>`;
 const actions=document.getElementById('page-actions');const actionsKey=r.state+':'+state.busy;
 if(actions.dataset.key!==actionsKey){actions.innerHTML=controls(r);actions.dataset.key=actionsKey;if(state.busy)actions.querySelectorAll('button').forEach(b=>b.disabled=true);}
 const details=document.getElementById('detail-settings');details.innerHTML=`<div><dt>Run ID</dt><dd class="mono">${esc(r.id)}</dd></div><div><dt>AX phase</dt><dd>${esc(r.platformPhase)}</dd></div><div><dt>Workspace</dt><dd>/workspace</dd></div><div><dt>Last updated</dt><dd>${esc(time(r.updatedAt))}</dd></div>`;
 const resumable=['review','suspended','failed'].includes(r.state);document.getElementById('feedback-form').hidden=!resumable;
 document.getElementById('resume-button').disabled=state.busy;
 document.getElementById('feedback-hint').textContent=r.template==='codex-task'?'Same workspace. Same conversation.':'Runs the check again with your new note.';
 const outcome=document.getElementById('run-outcome');outcome.hidden=resumable;
 outcome.textContent=['completed','cancelled'].includes(r.state)?'Run closed. Your conversation and saved copies are still available.':['browsing','opening-workspace','closing-workspace'].includes(r.state)?'Close the workspace to continue the conversation.':'You can continue when this turn ends.';
 const warning=document.getElementById('run-error');warning.hidden=!r.error;warning.textContent=r.error??'';
 if(changed&&state.tab==='files')loadWorkspace().catch(e=>error(e.message));
}
function appendAgentText(node,delta){
 // Keep the unmodified buffer: a later streaming chunk may turn trailing spaces
 // or newlines into meaningful word/paragraph separators. Only trim the display.
 const text=node.querySelector('.message-text');
 node.agentText=(node.agentText??text.textContent??'')+String(delta??'');
 text.textContent=node.agentText.trimEnd();node.hidden=text.textContent.length===0;
}
function appendEvent(item){
 const container=document.getElementById('events');if(!container)return;
 container.querySelector('.events-empty')?.remove();const stick=container.scrollHeight-container.scrollTop-container.clientHeight<100,last=container.lastElementChild;
 if(item.kind==='agent'&&last?.dataset.kind==='agent'){appendAgentText(last,item.text);}
 else if(last?.dataset.kind==='command'&&['command-output','command-result'].includes(item.kind)){
  const pre=last.querySelector('pre');pre.textContent+=(last.dataset.streamKind===item.kind?'':'\n\n')+item.text;last.dataset.streamKind=item.kind;
 }
 else if(['stdout','stderr','command-output'].includes(item.kind)&&last?.dataset.kind===item.kind){last.querySelector('pre').textContent+=item.text;}
 else{
  const technical=['system','exit'].includes(item.kind),tool=['command','command-output','command-result','stdout','stderr','changes'].includes(item.kind);
  const node=document.createElement(tool||technical?'details':'article');node.className=tool?'tool-event':technical?'system-event':'message';node.dataset.kind=item.kind;
  if(tool||technical){const summary=document.createElement('summary');const name=technical?'System':item.kind==='changes'?'File changes':item.kind==='stderr'?'Error output':item.kind==='stdout'?'Command output':item.kind==='command-result'?'Command result':item.kind==='command-output'?'Command output':'Command';summary.innerHTML=`${icon(technical?'info':item.kind==='changes'?'file':'terminal')}<span class="event-type">${name}</span><span class="event-summary"></span>${icon('chevron')}`;summary.querySelector('.event-summary').textContent=String(item.text).split('\n').find(line=>line.trim())?.slice(0,100)??'';const pre=document.createElement('pre');pre.textContent=item.text;node.append(summary,pre);}
  else{const speaker=item.kind==='user'?'You':item.kind==='agent'?'Codex':item.kind==='error'?'Run error':label(item.kind);node.innerHTML=`<div class="message-avatar ${item.kind==='user'?'user-avatar':''}">${icon(item.kind==='user'?'chat':item.kind==='agent'?'spark':'info')}</div><div class="message-body"><header><strong></strong><time></time></header><div class="message-text"></div></div>`;node.querySelector('strong').textContent=speaker;node.querySelector('time').textContent=shortTime(item.createdAt);if(item.kind==='agent')appendAgentText(node,item.text);else node.querySelector('.message-text').textContent=item.text;}
  container.append(node);
 }
 if(stick)container.scrollTop=container.scrollHeight;
}
function openStream(id){closeStream();const es=new EventSource(`/api/runs/${encodeURIComponent(id)}/events?after=${state.cursor}`);state.stream=es;
 es.onopen=()=>{if(state.run?.id!==id)return;const s=document.getElementById('stream-state');if(s)s.textContent='Live';};
 es.onmessage=event=>{if(state.run?.id!==id)return;let item;try{item=JSON.parse(event.data);}catch{return;}if(state.seen.has(item.id))return;state.seen.add(item.id);state.cursor=item.id;appendEvent(item);};
 es.onerror=()=>{if(state.run?.id!==id)return;const s=document.getElementById('stream-state');if(s)s.textContent='Reconnecting…';};
}
function selectRunTab(){const files=state.tab!=='activity';for(const name of ['activity','files']){const el=document.getElementById(name+'-tab');if(!el)continue;const selected=name==='files'?files:!files;el.setAttribute('aria-selected',String(selected));el.tabIndex=selected?0:-1;}document.getElementById('activity-panel').hidden=files;document.getElementById('files-panel').hidden=!files;}
function breadcrumbs(path,exported=false){const parts=path?path.split('/'):[],action=exported?'export-dir':'workspace-dir';return `<nav class="breadcrumbs" aria-label="File location"><button type="button" data-action="${action}" data-path="" ${!path?'aria-current="location"':''}>${icon('folder')}${exported?'Saved copy':'Workspace'}</button>${parts.map((part,index)=>`${icon('chevron')}<button type="button" data-action="${action}" data-path="${esc(parts.slice(0,index+1).join('/'))}" ${index===parts.length-1?'aria-current="location"':''}>${esc(part)}</button>`).join('')}</nav>`;}
function fileHeader(path,{exported=false,active=false,canOpen=false}={}){return `<div class="file-toolbar"><div class="segmented" aria-label="File source"><button type="button" data-action="files" aria-pressed="${!exported}">Workspace</button><button type="button" data-action="exports" aria-pressed="${exported}">Saved copies</button></div><div class="file-tools">${active?`<span class="live-indicator">Live</span>${iconButton('Refresh folder','workspace-refresh','refresh')}<details class="action-menu"><summary class="btn icon-button" aria-label="File actions" title="File actions">${icon('more')}</summary><div class="menu-content">${button('Save export','workspace-export','','','download')}${state.run?.state==='browsing'?button('Close workspace','close-workspace','','','close'):''}</div></details>`:exported?iconButton('Refresh saved copies','exports-refresh','refresh'):canOpen?'<span class="muted small">Paused</span>':''}</div></div>${active||exported?`<div class="path-toolbar">${path?`<button type="button" class="btn icon-button" data-action="${exported?'export-dir':'workspace-dir'}" data-path="${esc(path.split('/').slice(0,-1).join('/'))}" aria-label="Up one folder" title="Up one folder">${icon('back')}</button>`:''}${breadcrumbs(path,exported)}</div>`:''}`;}
function fileList(entries,path,exported=false){
 const sorted=[...entries].sort((a,b)=>(a.kind==='directory'?0:1)-(b.kind==='directory'?0:1)||a.name.localeCompare(b.name));
 if(!sorted.length)return '<div class="folder-empty">This folder is empty.</div>';
 return `<div class="file-columns" aria-hidden="true"><span>Name</span><span>Type</span><span>Size</span></div><ul class="file-list" aria-label="Files">${sorted.map(e=>{const p=path?path+'/'+e.name:e.name,folder=e.kind==='directory',blocked=e.kind==='blocked',action=exported?(folder?'export-dir':'preview-file'):(folder?'workspace-dir':'workspace-file');return `<li><button type="button" title="${esc(e.name)}" class="file-row ${state.selectedPath===p?'selected':''}" data-action="${action}" data-path="${esc(p)}" ${blocked?'disabled':''} ${!folder&&!blocked?`aria-pressed="${state.selectedPath===p}"`:''}><span class="file-name">${icon(folder?'folder':/\.(js|ts|py|json|html|css|cs|yaml|yml|sh)$/i.test(e.name)?'code':'file',folder?'folder-icon':'')}<span>${esc(e.name)}</span></span><span class="file-type">${folder?'Folder':blocked?'Unavailable':esc(fileType(e.name))}</span><span class="file-size">${folder?'—':blocked?'—':fileSize(e.size)}</span></button></li>`;}).join('')}</ul>`;
}
function fileBrowser(entries,path,exported=false){return `<div class="file-browser"><div class="directory-pane">${fileList(entries,path,exported)}</div><section id="file-preview" class="preview-pane" aria-label="File preview">${emptyState('file','Select a file','Preview it here or download a copy.')}</section></div>`;}
async function loadWorkspace(path=state.workspacePath){
 const r=state.run;if(!r||state.tab!=='files')return;state.workspacePath=path;state.selectedPath=null;const request=++state.fileRequest;state.previewRequest++;
 const panel=document.getElementById('files-panel');if(!panel)return;
 const active=r.platformPhase==='Running'&&['running','browsing'].includes(r.state),canOpen=['review','suspended','failed'].includes(r.state);
 if(!active){panel.innerHTML=fileHeader('',{canOpen})+emptyState('folder',r.terminal?'Workspace closed':canOpen?'Open your workspace':'Preparing your workspace',r.terminal?'The sandbox was deleted. Any saved copies are still available.':canOpen?'Browse the files in your sandbox. Opening starts no AI turn.':'Files will be available once the sandbox is ready.',canOpen?button('Open workspace','browse','primary',false,'folder'):r.terminal?button('View saved copies','exports'):'' );return;}
 panel.innerHTML=fileHeader(path,{active:true})+'<div class="folder-loading" role="status">Loading files…</div>';
 try{
  const listing=await api(`/runs/${r.id}/workspace?path=${encodeURIComponent(path)}`);
  if(request!==state.fileRequest||state.run?.id!==r.id||state.tab!=='files'||state.workspacePath!==path||state.run.platformPhase!=='Running'||!['running','browsing'].includes(state.run.state))return;
  panel.innerHTML=fileHeader(path,{active:true})+fileBrowser(listing.entries,path)+`<footer class="file-footer"><span>${listing.entries.length} items${listing.truncated?' · Listing limited':''}</span><span>Read-only · Live files${listing.skipped?' · Some entries hidden':''}</span></footer>`;
 }catch(e){if(request!==state.fileRequest||state.run?.id!==r.id||state.tab!=='files')return;panel.innerHTML=fileHeader(path,{active:true})+emptyState('info','Couldn’t load this folder',esc(e.message),button('Try again','workspace-refresh'));throw e;}
}
function selectFile(path){state.selectedPath=path;document.querySelectorAll('.file-row').forEach(row=>{const selected=row.dataset.path===path;row.classList.toggle('selected',selected);if(row.hasAttribute('aria-pressed'))row.setAttribute('aria-pressed',String(selected));});}
async function previewWorkspace(path){
 const id=state.run?.id,folder=state.workspacePath,request=++state.previewRequest;if(!id)return;selectFile(path);
 const pane=document.getElementById('file-preview');if(pane)pane.innerHTML='<div class="folder-loading" role="status">Loading preview…</div>';
 const result=await api(`/runs/${id}/workspace/content?path=${encodeURIComponent(path)}`);
 if(request!==state.previewRequest||state.run?.id!==id||state.tab!=='files'||state.workspacePath!==folder)return;
 renderPreview(result,path,`/api/runs/${id}/workspace/download?path=${encodeURIComponent(path)}`,false);
}
function renderPreview(result,path,url,exported){const pane=document.getElementById('file-preview');if(!pane)return;pane.innerHTML=`<header class="preview-heading"><div>${icon('file')}<strong>${esc(path.split('/').pop())}</strong></div><a class="btn icon-button" href="${url}" download aria-label="Download ${esc(path.split('/').pop())}" title="Download file">${icon('download')}</a></header><div class="preview-meta">${fileSize(result.size)} · ${exported?'Saved copy':'Live file'}${result.truncated?' · Preview truncated':''}</div>${result.isBinary?emptyState('file','Preview unavailable','Download this file to open it.'): '<pre id="file-content" class="file-content" tabindex="0" aria-label="File contents"></pre>'}`;const text=document.getElementById('file-content');if(text)text.textContent=result.text||'(Empty file)';}
function exportedEntries(files,path){const prefix=path?path+'/':'',result=new Map();for(const f of files){if(!f.path.startsWith(prefix))continue;const rest=f.path.slice(prefix.length),slash=rest.indexOf('/'),name=slash<0?rest:rest.slice(0,slash);if(name)result.set(name,slash<0?{name,kind:'file',size:f.size}:{name,kind:'directory'});}return [...result.values()];}
async function loadExports(path=state.exportPath){
 const id=state.run?.id,request=++state.fileRequest;if(!id||state.tab!=='exports')return;state.exportPath=path;state.selectedPath=null;state.previewRequest++;
 const panel=document.getElementById('files-panel');if(!panel)return;panel.innerHTML=fileHeader(path,{exported:true})+'<div class="folder-loading" role="status">Loading saved copies…</div>';
 const result=await api(`/runs/${id}/files`);if(request!==state.fileRequest||state.run?.id!==id||state.tab!=='exports'||state.exportPath!==path)return;
 const snapshot=result.snapshot;state.files=snapshot;state.fileRun=id;
 panel.innerHTML=fileHeader(path,{exported:true})+(snapshot?fileBrowser(exportedEntries(snapshot.files,path),path,true)+`<footer class="file-footer"><span>Saved ${esc(time(snapshot.capturedAt))} · Turn ${snapshot.turn}</span><span>${snapshot.files.length} files · Not live</span></footer>`:emptyState('download','No saved copies yet','In your open workspace, choose File actions → Save export to keep a copy after the run is closed.',button('Go to workspace','files')));
}
async function previewExport(path){const id=state.run?.id,snapshot=state.files,folder=state.exportPath,request=++state.previewRequest;if(!id||!snapshot)return;selectFile(path);const pane=document.getElementById('file-preview');if(pane)pane.innerHTML='<div class="folder-loading" role="status">Loading preview…</div>';const query=`path=${encodeURIComponent(path)}&turn=${snapshot.turn}`,result=await api(`/runs/${id}/files/content?${query}`);if(request!==state.previewRequest||state.run?.id!==id||state.files!==snapshot||state.tab!=='exports'||state.exportPath!==folder)return;renderPreview(result,path,`/api/runs/${id}/files/download?${query}`,true);}
async function route(){
 if(!state.session?.authenticated)return;const epoch=++state.epoch;closeStream();state.run=null;state.error='';state.fileRequest++;state.previewRequest++;state.route=location.hash.replace(/^#\/?/,'')||'new';
 if(state.route==='new')renderNew();
 else if(state.route==='connections'){shell('<div class="panel loading-panel" role="status">Loading connection…</div>');const c=await api('/connections/codex');if(epoch!==state.epoch)return;state.connection=c;state.github=await api('/connections/github');if(epoch!==state.epoch)return;renderConnections();}
 else if(state.route.startsWith('runs/')){shell('<div class="panel loading-panel" role="status">Loading run…</div>');const r=await api('/runs/'+encodeURIComponent(state.route.split('/')[1]));if(epoch===state.epoch)renderDetail(r);}
 else{state.route='runs';renderRuns();}
}
async function load(){try{if(!await session()){renderLogin();return;}[state.catalog,state.runs]=await Promise.all([api('/catalog'),api('/runs')]);await route();}catch(e){root.innerHTML=`<main class="login-page"><section class="login-card">${emptyState('info','Can’t reach Agent Desk','The lab may be paused to protect host resources. Try again shortly.',button('Try again','retry-load','primary'))}</section></main>`;}}
async function runAction(action){const id=state.run?.id;if(!id)return;if(action==='finish'&&!confirm('Finish this run? The sandbox and live workspace will be deleted. Only saved copies and conversation history remain. Unpublished Git commits will NOT be pushed.'))return;if(action==='cancel'&&!confirm('Cancel this run and delete its sandbox? Unpublished Git commits and unsaved workspace files will be lost.'))return;
 if(action==='publish'&&!confirm(`Publish checked commit ${state.run.publication?.head?.slice(0,12)} to ${state.run.repository.fullName} on this run’s branch and create/update its draft PR? Nothing will be merged.`))return;
 const r=await mutate(`/runs/${id}/${action}`,{message:action==='resume'?(state.drafts[id]??''):action==='publish'?state.run.publication.head:''});if(action==='resume'){state.drafts[id]='';const feedback=document.getElementById('feedback');if(feedback)feedback.value='';}if(state.run?.id===id)updateDetail(r);
}
root.addEventListener('input',e=>{if(['repository-baseBranch','repository-checkCommand'].includes(e.target.id))state.repoForm[e.target.id.slice(11)]=e.target.value;if(['title','instructions'].includes(e.target.id))state.form[e.target.id]=e.target.value;if(e.target.id==='feedback'&&state.run)state.drafts[state.run.id]=e.target.value;if(e.target.id==='run-search'){state.runSearch=e.target.value;document.getElementById('run-list').innerHTML=runRows();}});
root.addEventListener('change',e=>{if(e.target.id==='github-installation'){state.githubInstallationId=e.target.value;renderConnections();}if(e.target.id==='repository-id'){state.repoForm.id=e.target.value;state.repoForm.baseBranch=state.repositories.find(r=>String(r.id)===e.target.value)?.defaultBranch??'';renderRepositoryForm();}if(e.target.id==='repository-publishMode'){state.repoForm.publishMode=e.target.value;renderRepositoryForm();}if(e.target.id==='template'){state.form.template=e.target.value;updateNewSettings();}if(e.target.id==='system-events'){state.systemEvents=e.target.checked;document.getElementById('events').classList.toggle('show-system',state.systemEvents);}if(e.target.id==='run-filter'){state.runFilter=e.target.value;document.getElementById('run-list').innerHTML=runRows();}});
root.addEventListener('submit',async e=>{e.preventDefault();if(state.busy)return;state.busy=true;const submit=e.target.querySelector('button[type=submit]');if(submit)submit.disabled=true;error('');try{
 if(e.target.id==='login-form'){await api('/login',{method:'POST',body:{username:e.target.username.value,password:e.target.password.value}});e.target.password.value='';await load();}
 if(e.target.id==='run-form'){const input={...state.form};if(input.template==='codex-task'&&state.repoForm.id){input.repository={repositoryId:Number(state.repoForm.id),baseBranch:state.repoForm.baseBranch,checkCommand:state.repoForm.checkCommand,publishMode:state.repoForm.publishMode};if(input.repository.publishMode==='auto'&&!confirm('Automatically push committed changes and create/update a draft PR after every successful turn and required check? Nothing will be merged.'))return;}const r=await mutate('/runs',input);state.form={...state.form,title:'',instructions:''};state.runs=[r,...state.runs.filter(existing=>existing.id!==r.id)];location.hash=`/runs/${r.id}`;}
 if(e.target.id==='feedback-form')await runAction('resume');
 if(e.target.id==='github-install-form'){const allowAllRepositories=e.target.elements.namedItem('allowAllRepositories')?.checked===true;state.github=await api('/connections/github/installation',{method:'POST',body:{id:Number(e.target.installation.value),allowAllRepositories}});state.githubInstallations=[];renderConnections();}
 }catch(ex){error(ex.message);}finally{state.busy=false;if(submit)submit.disabled=false;if(state.run&&document.getElementById('detail-settings'))updateDetail(state.run);}});
root.addEventListener('click',async e=>{
 if(e.target.closest('.skip-link')){e.preventDefault();document.getElementById('main-content')?.focus();return;}
 const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;if(action==='theme'){window.portalTheme?.toggle();return;}if(state.busy)return;state.busy=true;target.disabled=true;error('');try{
 if(action==='retry-load'){await load();}
 else if(action==='load-repositories'){state.repositories=await api('/repositories');renderRepositoryForm();document.querySelector('.repository-settings').open=true;}
 else if(action==='github-setup'){const setup=await api('/connections/github/setup',{method:'POST',body:{}});if(!setup.url.startsWith('https://github.com/settings/apps/new?state='))throw new Error('Unexpected GitHub setup URL.');const form=document.createElement('form');form.method='POST';form.action=setup.url;const input=document.createElement('input');input.type='hidden';input.name='manifest';input.value=JSON.stringify(setup.manifest);form.append(input);document.body.append(form);form.submit();}
 else if(action==='github-refresh'){state.githubInstallations=await api('/connections/github/installations');if(!state.githubInstallations.length)throw new Error('No active installation found. Install the App on GitHub, then refresh.');renderConnections();}
 else if(action==='github-disconnect'){if(!confirm('Disconnect GitHub? Existing runs cannot publish until their original connection is available. This does not uninstall the App on GitHub.'))return;state.github=await api('/connections/github/disconnect',{method:'POST',body:{}});state.githubInstallations=[];renderConnections();}
 else if(['files','workspace-refresh','workspace-dir'].includes(action)){state.tab='files';selectRunTab();await loadWorkspace(action==='workspace-dir'?target.dataset.path:undefined);}
 else if(['exports','exports-refresh','export-dir'].includes(action)){state.tab='exports';selectRunTab();await loadExports(action==='export-dir'?target.dataset.path:undefined);}
 else if(action==='workspace-file')await previewWorkspace(target.dataset.path);
 else if(action==='preview-file')await previewExport(target.dataset.path);
 else if(action==='workspace-export'){if(!confirm('Save a copy of eligible workspace files? Copies survive sandbox deletion. Do not include secrets.'))return;await api(`/runs/${state.run.id}/workspace/export`,{method:'POST',body:{}});state.tab='exports';state.exportPath='';selectRunTab();await loadExports();}
 else if(action==='activity'){state.tab='activity';state.fileRequest++;state.previewRequest++;selectRunTab();}
 else if(action.startsWith('codex-')){const method=action==='codex-login'?'login':action==='codex-cancel'?'cancel':'disconnect';if(method==='disconnect'&&!confirm('Disconnect your saved ChatGPT account?'))return;state.connection=await api('/connections/codex/'+method,{method:'POST',body:{}});if(state.catalog?.connections?.[0])state.catalog.connections[0].state=state.connection.state;renderConnections();}
 else if(action==='logout'){await api('/logout',{method:'POST'});clearPrivateState();await session();renderLogin();}
 else if(state.run&&['resume','suspend','finish','cancel','browse','close-workspace','publish'].includes(action))await runAction(action);
 }catch(ex){error(ex.message);}finally{state.busy=false;target.disabled=false;document.querySelectorAll('.action-menu[open]').forEach(menu=>menu.open=false);if(state.run&&document.getElementById('detail-settings'))updateDetail(state.run);}
});
root.addEventListener('keydown',e=>{
 if(e.key==='Escape'){document.querySelectorAll('.action-menu[open],.account-menu[open]').forEach(menu=>{menu.open=false;menu.querySelector('summary')?.focus();});}
 const tab=e.target.closest('[role="tab"]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=document.getElementById((e.key==='Home'||e.key==='ArrowLeft'?'activity':'files')+'-tab');next.focus();next.click();}
 if(e.target.closest('.file-row')&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const rows=[...document.querySelectorAll('.file-row:not(:disabled)')],index=rows.indexOf(e.target.closest('.file-row')),next=e.key==='Home'?0:e.key==='End'?rows.length-1:Math.max(0,Math.min(rows.length-1,index+(e.key==='ArrowDown'?1:-1)));rows[next]?.focus();}
});
window.addEventListener('hashchange',()=>route().catch(e=>error(e.message)));
setInterval(async()=>{
 if(!state.session?.authenticated||state.busy)return;const epoch=state.epoch,id=state.run?.id;
 try{
  if(state.route==='connections'){const c=await api('/connections/codex');if(epoch!==state.epoch||state.busy)return;if(JSON.stringify(c)!==JSON.stringify(state.connection)){state.connection=c;if(state.catalog?.connections?.[0])state.catalog.connections[0].state=c.state;renderConnections();}}
  const runs=await api('/runs');if(epoch!==state.epoch||state.busy)return;state.runs=runs;const count=document.getElementById('run-count');if(count)count.textContent=String(runs.length);
  if(state.route==='runs'&&!document.getElementById('run-list')?.contains(document.activeElement)){const list=document.getElementById('run-list');if(list)list.innerHTML=runRows();}
  if(id){const r=await api('/runs/'+id);if(epoch===state.epoch&&state.run?.id===id&&!state.busy)updateDetail(r);}
 }catch(ex){if(epoch===state.epoch)error(ex.message);}
},2500);
load();
